// - Detecta bossbar â Cidade (confirma DOM) â hunt ativa
// - start()/stop() controlados pela extensÃ£o

(function () {
    const ACTION_COOLDOWN_MS = 20000;
    const STORAGE_KEY_LAST_ACTION = '__baiakIdlePularBossLastActionAt';

    class BaiakIdlePularBossModule {
        constructor() {
            this._observer = null;
            this._running = false;
            this._busy = false;
        }

        _log(msg, extra) {}

        _sel() {
            return window.BaiakIdleSeletores || null;
