                try {
                    input.value = value;
                } catch (__) {}
            }

            try {
                if (typeof InputEvent === 'function') {
                    input.dispatchEvent(
                        new InputEvent('input', {
                            bubbles: true,
                            cancelable: true,
                            composed: true,
                            data: value === '' ? null : value,
                            inputType: value === '' ? 'deleteContentBackward' : 'insertFromPaste'
