                    );
                } else {
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                }
            } catch (_) {
                try {
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                } catch (__) {}
            }
            try {
                input.dispatchEvent(new Event('keyup', { bubbles: true }));
                input.dispatchEvent(new Event('change', { bubbles: true }));
            } catch (_) {}

            return String(input.value || '') === value;
        }

