// MÃ³dulo Baiak Idle (MAIN): Reconect
// - Sem char online (party/HUD/wave) â F5 a cada 30s
// - NavegaÃ§Ã£o home â /jogar/ fica no background da extensÃ£o

(function () {
  if (typeof window.BaiakIdleReconectModule !== 'undefined') return;

  const CHECK_MS = 2000;
  const RELOAD_EVERY_MS = 30000;

  class BaiakIdleReconectModule {
    constructor() {
      this._running = false;
      this._pollTimer = null;
      this._noCharSince = 0;
    }

    _sel() {
      return window.BaiakIdleSeletores || null;
    }

    /**
     * True se houver indÃ­cio de personagem online no DOM.
     */
    _hasOnlineChar() {
      try {
        const Sel = this._sel();
        if (Sel?.getCharactersSnapshot) {
          const list = Sel.getCharactersSnapshot();
          if (Array.isArray(list) && list.length > 0) return true;
        }
      } catch (_) {}

      try {
        const members = document.querySelectorAll('#party-list .member, .party .member');
        if (members.length > 0) return true;
      } catch (_) {}

      try {
        const nick =
          document.getElementById('hud-nick') || document.querySelector('.hud-nick');
        const nickText = String(nick?.textContent || '').trim();
        if (nickText && nickText !== 'TibiaBot.Online') return true;
      } catch (_) {}

      try {
        const wave =
          document.getElementById('wave-title') || document.querySelector('#wave-title');
        if (wave && String(wave.textContent || '').trim()) return true;
      } catch (_) {}

      return false;
    }

    _tick() {
      if (!this._running) return;

      if (this._hasOnlineChar()) {
        this._noCharSince = 0;
        return;
      }

      const now = Date.now();
      if (!this._noCharSince) {
        this._noCharSince = now;
        return;
      }

      if (now - this._noCharSince < RELOAD_EVERY_MS) return;

      this._noCharSince = now;
      try {
        location.reload();
      } catch (_) {
        try {
          window.location.href = String(window.location.href || '');
        } catch (__) {}
      }
    }

    _startPoll() {
      this._stopPoll();
      this._pollTimer = setInterval(() => {
        this._tick();
      }, CHECK_MS);
    }

    _stopPoll() {
      if (this._pollTimer) {
        clearInterval(this._pollTimer);
        this._pollTimer = null;
      }
    }

    start() {
      if (this._running) {
        this._tick();
        return { success: true, already: true };
      }
      this._running = true;
      this._noCharSince = 0;
      this._startPoll();
      this._tick();
      return { success: true };
    }

    stop() {
      this._stopPoll();
      this._running = false;
      this._noCharSince = 0;
      return { success: true };
    }

    isRunning() {
      return !!this._running;
    }
  }

  window.BaiakIdleReconectModule = BaiakIdleReconectModule;

  try {
    if (!window.__baiakIdleReconect) {
      window.__baiakIdleReconect = new BaiakIdleReconectModule();
    }
    if (window.__BAIAKIDLE_AUTO_START_RECONECT__) {
      window.__baiakIdleReconect.start();
    }
  } catch (err) {
    console.error('[BaiakIdle Reconect] Falha no bootstrap', err);
  }
})();

