// MÃ³dulo Baiak Idle (MAIN): Stamina
// - % mÃ­nima â Treino online
// - % mÃ¡xima â volta para a hunt ativa
// - Poll a cada 30s (sem MutationObserver â o texto da stamina muda demais)
// Config: window.__baiakIdleStaminaConfig = { minPct, maxPct }

(function () {
    const POLL_MS = 30000;
    const ACTION_COOLDOWN_MS = 25000;
    const DEFAULT_MIN = 15;
    const DEFAULT_MAX = 30;
    const STORAGE_KEY_LAST_ACTION = '__baiakIdleStaminaLastActionAt';
    const STORAGE_KEY_MODE = '__baiakIdleStaminaMode';

    class BaiakIdleStaminaModule {
        constructor() {
            this._timer = null;
            this._running = false;
            this._busy = false;
        }

        _log(msg, extra) {
            try {
                if (extra !== undefined) {
                    console.log('[BaiakIdle Stamina]', msg, extra);
                } else {
                    console.log('[BaiakIdle Stamina]', msg);
                }
            } catch (_) {}
        }

        _sel() {
            return window.BaiakIdleSeletores || null;
        }

        _getWaveTitle() {
            const S = this._sel();
            if (typeof S?.getWaveTitleText === 'function') {
                return String(S.getWaveTitleText() || '').trim();
            }
            try {
                const el = document.querySelector('#wave-title');
                return String(el?.textContent || '').trim();
            } catch (_) {
                return '';
            }
        }

        _isInExercise() {
            const S = this._sel();
            if (typeof S?.isInExercise === 'function') return !!S.isInExercise();
            const t = this._getWaveTitle().toLowerCase();
            return t === 'treino online' || t.indexOf('treino') !== -1 || t.indexOf('exercise') !== -1;
        }

        _isInCity() {
            const S = this._sel();
            if (typeof S?.isInCity === 'function') return !!S.isInCity();
            return this._getWaveTitle().toLowerCase() === 'cidade';
        }

        /** JÃ¡ estÃ¡ caÃ§ando (nem cidade, nem treino). */
        _isInHuntSpot() {
            const title = this._getWaveTitle();
            if (!title) return false;
            return !this._isInCity() && !this._isInExercise();
        }

        /** LÃª #stamina-pct (helper do seletor ou fallback direto). */
        _readStaminaPct() {
            const S = this._sel();
            if (typeof S?.getStaminaPct === 'function') {
                const pct = S.getStaminaPct();
                if (pct != null) return pct;
            }
            try {
                const el =
                    (S?.STAMINA?.PCT && S.findElement?.(S.STAMINA.PCT, 'STAMINA_PCT')) ||
                    document.querySelector('#stamina-pct') ||
                    document.querySelector('b#stamina-pct');
                if (!el) return null;
                const m = String(el.textContent || '').trim().match(/(\d+(?:[.,]\d+)?)/);
                if (!m) return null;
                const n = parseFloat(String(m[1]).replace(',', '.'));
                if (!Number.isFinite(n)) return null;
                return Math.max(0, Math.min(100, n));
            } catch (_) {
                return null;
            }
        }

        _readConfig() {
            const raw = window.__baiakIdleStaminaConfig;
            let minPct = DEFAULT_MIN;
            let maxPct = DEFAULT_MAX;
            if (raw && typeof raw === 'object') {
                if (Number.isFinite(Number(raw.minPct))) minPct = Number(raw.minPct);
                if (Number.isFinite(Number(raw.maxPct))) maxPct = Number(raw.maxPct);
            }
            minPct = Math.max(0, Math.min(100, Math.round(minPct)));
            maxPct = Math.max(0, Math.min(100, Math.round(maxPct)));
            if (minPct >= maxPct) {
                return { minPct: DEFAULT_MIN, maxPct: DEFAULT_MAX, invalid: true };
            }
            return { minPct, maxPct, invalid: false };
        }

        _canActNow() {
            try {
                const raw = sessionStorage.getItem(STORAGE_KEY_LAST_ACTION);
                const last = raw ? parseInt(raw, 10) : 0;
                if (!last) return true;
                return Date.now() - last >= ACTION_COOLDOWN_MS;
            } catch (_) {
                return true;
            }
        }

        _markAction(mode) {
            try {
                sessionStorage.setItem(STORAGE_KEY_LAST_ACTION, String(Date.now()));
                if (mode) sessionStorage.setItem(STORAGE_KEY_MODE, String(mode));
            } catch (_) {}
        }

        _clearMode() {
            try {
                sessionStorage.removeItem(STORAGE_KEY_MODE);
            } catch (_) {}
        }

        async _goExercise() {
            this._busy = true;
            try {
                const Teleporte = window.BaiakIdleTeleporte;
                if (!Teleporte?.goToExercise) {
                    this._log('BaiakIdleTeleporte.goToExercise indisponÃ­vel');
                    this._clearMode();
                    return;
                }
                const result = await Teleporte.goToExercise();
                if (result?.success) {
                    this._markAction('exercise');
                    this._log('Chegou no Treino online');
                } else {
                    this._clearMode();
                    this._log('NÃ£o foi para o treino', result);
                }
            } catch (err) {
                this._clearMode();
                this._log('Erro ao ir para treino', err);
            } finally {
                this._busy = false;
            }
        }

        async _goHunt() {
            this._busy = true;
            try {
                const Teleporte = window.BaiakIdleTeleporte;
                if (!Teleporte?.goToHunt) {
                    this._log('BaiakIdleTeleporte.goToHunt indisponÃ­vel');
                    this._clearMode();
                    return;
                }
                const result = await Teleporte.goToHunt();
                if (result?.success) {
                    this._markAction('hunt');
                    this._log('Voltou para a hunt');
                } else {
                    this._clearMode();
                    this._log('NÃ£o voltou para a hunt', result);
                }
            } catch (err) {
                this._clearMode();
                this._log('Erro ao voltar para a hunt', err);
            } finally {
                this._busy = false;
            }
        }

        _tick() {
            if (!this._running || this._busy) return;
            if (window.BaiakIdleTeleporte?.busy) return;

            try {
                const pct = this._readStaminaPct();
                if (pct == null) {
                    this._log('Stamina % nÃ£o encontrada no DOM (#stamina-pct)');
                    return;
                }

                const cfg = this._readConfig();
                if (cfg.invalid) {
                    this._log('Config invÃ¡lida (mÃ­n >= mÃ¡x). Usando padrÃ£o.', cfg);
                }

                if (pct <= cfg.minPct) {
                    // JÃ¡ no treino â ok. Antes: mode=exercise no sessionStorage
                    // travava retries se o teleporte tivesse falhado.
                    if (this._isInExercise()) return;
                    if (!this._canActNow()) {
                        this._log(`Stamina ${pct}% â¤ ${cfg.minPct}% (cooldown)`);
                        return;
                    }
                    this._log(
                        `Stamina ${pct}% â¤ ${cfg.minPct}% â Treino online (onde: ${this._getWaveTitle() || '?'})`
                    );
                    void this._goExercise();
                    return;
                }

                if (pct >= cfg.maxPct) {
                    if (this._isInHuntSpot()) return;
                    if (!this._canActNow()) {
                        this._log(`Stamina ${pct}% â¥ ${cfg.maxPct}% (cooldown)`);
                        return;
                    }
                    this._log(
                        `Stamina ${pct}% â¥ ${cfg.maxPct}% â Hunt (onde: ${this._getWaveTitle() || '?'})`
                    );
                    void this._goHunt();
                }
            } catch (err) {
                this._log('Erro no tick de stamina', err);
            }
        }

        start() {
            if (this._running) {
                this._tick();
                return { success: true, alreadyRunning: true };
            }

            this._running = true;
            this._busy = false;
            // Limpa mode preso de sessÃµes anteriores (falha antiga â nunca mais viajava)
            this._clearMode();
            const cfg = this._readConfig();
            this._log(
                `MÃ³dulo iniciado (mÃ­n ${cfg.minPct}% â treino, mÃ¡x ${cfg.maxPct}% â hunt, poll ${POLL_MS / 1000}s)`
            );

            this._tick();
            this._timer = setInterval(() => this._tick(), POLL_MS);

            return { success: true };
        }

        stop() {
            if (this._timer) {
                clearInterval(this._timer);
                this._timer = null;
            }
            this._running = false;
            this._busy = false;
            this._log('MÃ³dulo parado');
            return { success: true };
        }

        isRunning() {
            return !!this._running;
        }
    }

    window.BaiakIdleStaminaModule = BaiakIdleStaminaModule;

    try {
        const prev = window.__baiakIdleStamina;
        const wasRunning = !!prev?.isRunning?.();
        try {
            prev?.stop?.();
        } catch (_) {}
        window.__baiakIdleStamina = new BaiakIdleStaminaModule();
        if (wasRunning || window.__BAIAKIDLE_AUTO_START_STAMINA__) {
            window.__baiakIdleStamina.start();
        }
    } catch (err) {
        console.error('[BaiakIdle Stamina] Falha no bootstrap', err);
    }
})();

