// MÃ³dulo Baiak Idle (MAIN): XP/h real
// - LÃª #an-raw (XP Gain) e #an-session
// - PreferÃªncia: XP Gain Ã· tempo da Session Ã 3600 (mÃ©dia da sessÃ£o)
// - Fallback: delta XP na janela recente (se Session indisponÃ­vel)
// - Reseta ao mudar #wave-title, ao cair o XP Gain ou ao reiniciar Session
// - Emite MODULE_STATUS para o overlay (sem API)

(function () {
    const POLL_MS = 10000;
    const SAMPLE_MAX = 90;
    const RATE_HISTORY_MAX = 60;
    const WINDOW_MS = 5 * 60 * 1000;
    const MIN_DELTA_MS = 9000;
    const MIN_SESSION_SEC = 60;

    class BaiakIdleXpHoraModule {
        constructor() {
            this._timer = null;
            this._running = false;
            /** @type {{ t: number, xp: number, hunt: string, sessionSec: number }[]} */
            this._samples = [];
            /** @type {{ t: number, xph: number, hunt: string }[]} */
            this._rateHistory = [];
            this._huntKey = '';
            this._lastStatusKey = '';
            this._currentXph = null;
        }

        _log(msg, extra) {}

        _sel() {
            return window.BaiakIdleSeletores || null;
        }

        _readXpGain() {
            const S = this._sel();
            if (typeof S?.getXpGain === 'function') {
                const n = S.getXpGain();
                if (n != null) return n;
            }
            try {
                const el =
                    document.querySelector('#an-raw') ||
                    document.querySelector('b#an-raw');
                if (!el) return null;
                if (typeof S?.parseBrNumber === 'function') {
                    return S.parseBrNumber(el.textContent);
                }
                const raw = String(el.textContent || '')
                    .trim()
                    .replace(/[^\d]/g, '');
                if (!raw) return null;
                const n = Number(raw);
                return Number.isFinite(n) ? n : null;
            } catch (_) {
                return null;
            }
        }

        _readSessionEl() {
            try {
                return (
                    document.querySelector('#an-session') ||
                    document.querySelector('b#an-session') ||
                    null
                );
            } catch (_) {
                return null;
            }
        }

        _readSessionText() {
            const el = this._readSessionEl();
            if (!el) return '';
            return String(el.textContent || '').trim();
        }

        _readSessionSec() {
            try {
                const text = this._readSessionText();
                const m = text.match(/^(\d+):(\d{2}):(\d{2})$/);
                if (!m) return null;
                const h = parseInt(m[1], 10);
                const min = parseInt(m[2], 10);
                const sec = parseInt(m[3], 10);
                if (![h, min, sec].every((n) => Number.isFinite(n))) return null;
                return h * 3600 + min * 60 + sec;
            } catch (_) {
                return null;
            }
        }

        _readHuntKey() {
            const S = this._sel();
            if (typeof S?.getWaveTitleText === 'function') {
                return String(S.getWaveTitleText() || '').trim();
            }
            try {
                const el = document.querySelector('#wave-title');
                return String(el?.textContent || '').trim();
            } catch (_) {
                return '';
            }
        }

        _formatXp(n) {
            const v = Math.max(0, Math.round(Number(n) || 0));
            try {
                return v.toLocaleString('pt-BR');
            } catch (_) {
                return String(v).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
            }
        }

        _statusText(xphLabel) {
            return String(xphLabel || 'â¦');
        }

        _resetHistory(reason) {
            if (this._samples.length || this._rateHistory.length) {
                this._log('HistÃ³rico resetado', reason || '');
            }
            this._samples = [];
            this._rateHistory = [];
            this._currentXph = null;
        }

        /** XP/h = XP Gain Ã· Session Ã 3600. */
        _computeXphFromSession(xp, sessionSec) {
            if (xp == null || sessionSec == null) return null;
            if (sessionSec < MIN_SESSION_SEC) return null;
            if (xp < 0) return null;
            return (xp / sessionSec) * 3600;
        }

        /** Fallback: ritmo recente (delta XP na janela). */
        _computeXphFromWindow() {
            const samples = this._samples;
            if (samples.length < 2) return null;

            const last = samples[samples.length - 1];
            const cutoff = last.t - WINDOW_MS;
            let first = samples[0];
            for (let i = 0; i < samples.length - 1; i++) {
                if (samples[i].t >= cutoff) {
                    first = samples[i];
                    break;
                }
                first = samples[i];
            }

            const dt = last.t - first.t;
            const dx = last.xp - first.xp;
            if (dt < MIN_DELTA_MS || dx < 0) return null;
            return (dx / dt) * 3600000;
        }

        _computeXph(xp, sessionSec) {
            const fromSession = this._computeXphFromSession(xp, sessionSec);
            if (fromSession != null) return fromSession;
            return this._computeXphFromWindow();
        }

        _emitStatus(status, remainingText) {
            const text = remainingText || '';
            const key = `${status}|${text}|${this._running ? 1 : 0}`;
            if (key === this._lastStatusKey) return;
            this._lastStatusKey = key;

            try {
                window.postMessage(
                    {
                        source: 'TIBIA_BOT_MAIN',
                        type: 'MODULE_STATUS',
                        payload: {
                            botId: 'baiak_idle',
                            botLabel: 'Baiak-Idle',
                            moduleId: 'xp_hora',
                            moduleLabel: 'XP/h',
                            status,
                            remainingMs: 0,
                            remainingText: text,
                            running: !!this._running,
                            xph: this._currentXph
                        }
                    },
                    '*'
                );
            } catch (_) {}
        }

        _tick() {
            if (!this._running) return;

            try {
                const xp = this._readXpGain();
                const hunt = this._readHuntKey();
                const sessionSec = this._readSessionSec();
                const now = Date.now();

                if (xp == null) {
                    this._emitStatus('waiting', this._statusText('â¦'));
                    return;
                }

                if (hunt && hunt !== this._huntKey) {
                    this._huntKey = hunt;
                    this._resetHistory('hunt:' + hunt);
                }

                const prev = this._samples.length
                    ? this._samples[this._samples.length - 1]
                    : null;

                if (prev && xp < prev.xp) {
                    this._resetHistory('xp_gain_reset');
                }

                if (
                    prev &&
                    sessionSec != null &&
                    prev.sessionSec != null &&
                    sessionSec + 5 < prev.sessionSec
                ) {
                    this._resetHistory('session_reset');
                }

                if (!prev || now - prev.t >= POLL_MS * 0.7 || xp !== prev.xp) {
                    this._samples.push({
                        t: now,
                        xp,
                        hunt,
                        sessionSec: sessionSec != null ? sessionSec : prev?.sessionSec ?? 0
                    });
                    if (this._samples.length > SAMPLE_MAX) {
                        this._samples.splice(0, this._samples.length - SAMPLE_MAX);
                    }
                }

                const xph = this._computeXph(xp, sessionSec);
                if (xph == null) {
                    this._currentXph = null;
                    this._emitStatus('warming', this._statusText('â¦'));
                    return;
                }

                this._currentXph = xph;
                this._rateHistory.push({ t: now, xph, hunt });
                if (this._rateHistory.length > RATE_HISTORY_MAX) {
                    this._rateHistory.splice(
                        0,
                        this._rateHistory.length - RATE_HISTORY_MAX
                    );
                }

                this._emitStatus(
                    'xph',
                    this._statusText(this._formatXp(xph) + '/h')
                );
            } catch (err) {
                this._log('Erro no tick', err);
            }
        }

        getHistory() {
            return this._rateHistory.slice();
        }

        getCurrentXph() {
            return this._currentXph;
        }

        start() {
            if (this._running) {
                this._tick();
                return { success: true, alreadyRunning: true };
            }

            this._running = true;
