      this._busy = true;
      this._running = true;
      /** @type {{ id: string, gold: number, coins: number }[]} */
      const all = [];
      let pagesDone = 0;

      try {
        this._showModal({ mode: 'loading', detail: 'Pesquisando...' });
        await this._openMarketHistoricoGold();

        for (let page = 1; page <= PAGES; page++) {
