        for (let i = 0; i < all.length; i++) {
          const r = all[i];
          const key = r.id || i + ':' + r.gold + ':' + r.coins;
          if (seen.has(key)) continue;
          seen.add(key);
          totalGold += r.gold;
          totalCoins += r.coins;
        }

        if (totalGold <= 0 || seen.size === 0) {
          throw new Error('Nenhuma venda de gold encontrada no histÃ³rico.');
        }

        const coinsPer100m = (totalCoins / totalGold) * GOLD_UNIT;
        const result = {
          success: true,
          coinsPer100m,
          totalGold,
          totalCoins,
          count: seen.size,
          pages: pagesDone
        };

        this._showModal({
          mode: 'result',
          coinsPer100m,
          totalGold,
          totalCoins,
