// MÃ³dulo Baiak Idle (MAIN): Recarregar itens (silver token)
// - Monitora backpack/inv por itens vazios recarregÃ¡veis
// - Clique realista no item â botÃ£o com "recarregar" â confirma se aparecer
// - Custo: silver token (object 22516)

(function () {
  const POLL_MS = 1600;
  const BETWEEN_MS = 500;
  const MENU_WAIT_MS = 4000;
  const CONFIRM_WAIT_MS = 2500;
  const SETTLE_MS = 1000;
  const SKIP_MS = 20000;
  const STATUS_UI_MS = 1000;
  const SILVER_TOKEN_ID = 22516;
  const SILVER_TOKEN_NAME = 'silver token';

  /** Itens recarregÃ¡veis com silver token quando sem charges/wear. */
  const RECHARGE_BY_NAME = new Set([
    'spiritthorn ring',
    'might ring',
    'stone skin amulet',
    'ssa',
    'energy ring',
    'life ring',
    'ring of healing',
    'time ring',
    'stealth ring',
    'sword ring',
    'axe ring',
    'club ring',
    'power ring',
    'dwarven ring',
    'garlic necklace',
    'elven amulet',
    'protection amulet',
    'silver amulet',
    'bronze amulet',
    'strange talisman'
  ]);

  class BaiakIdleRecarregarItensModule {
    constructor() {
      this._running = false;
      this._busy = false;
      this._pollTimer = null;
      this._statusTimer = null;
      this._observer = null;
      this._lastStatusKey = '';
      this._lastAction = '';
      /** @type {Map<string|number, number>} */
      this._skipUntil = new Map();
    }

    _log(msg, extra) {
      try {
        if (window.__BAIAKIDLE_DEBUG) {
          console.log('[BaiakIdle Recarregar]', msg, extra || '');
        }
      } catch (_) {}
    }

    _sel() {
      return window.BaiakIdleSeletores || null;
    }

    _sleep(ms) {
      return new Promise((r) => setTimeout(r, ms));
    }

    async _waitFor(fn, timeoutMs, intervalMs = 100) {
      const start = Date.now();
      while (Date.now() - start < timeoutMs) {
        if (!this._running) return null;
        const v = fn();
        if (v) return v;
        await this._sleep(intervalMs);
      }
      return null;
    }

    _emitStatus(status, remainingText = '') {
      const key = `${status}|${remainingText}|${this._running ? 1 : 0}`;
      if (key === this._lastStatusKey) return;
      this._lastStatusKey = key;
      try {
        window.postMessage(
          {
            source: 'TIBIA_BOT_MAIN',
            type: 'MODULE_STATUS',
            payload: {
              botId: 'baiak_idle',
              botLabel: 'Baiak-Idle',
              moduleId: 'recarregar_itens',
              moduleLabel: 'Recarregar',
              status,
              remainingMs: 0,
              remainingText: String(remainingText || ''),
              running: !!this._running
            }
          },
          '*'
        );
      } catch (_) {}
    }

    _startStatusTicker() {
      if (this._statusTimer) return;
      const tick = () => {
        if (!this._running) {
          this._stopStatusTicker();
          this._emitStatus('stopped', '');
          return;
        }
        if (this._busy) {
          this._emitStatus('recharging', this._lastAction || 'â¦');
          return;
        }
        const tokens = this._countSilverTokens();
        if (tokens <= 0) {
          this._emitStatus('no_tokens', 'sem silver token');
          return;
        }
        const n = this._listCandidates().length;
        if (n > 0) {
          this._emitStatus('ready', tokens + ' tok Â· ' + n + ' vazio(s)');
        } else {
          this._emitStatus('idle', tokens + ' tok Â· ok');
        }
      };
      tick();
      this._statusTimer = setInterval(tick, STATUS_UI_MS);
    }

    _stopStatusTicker() {
      if (this._statusTimer) {
        clearInterval(this._statusTimer);
        this._statusTimer = null;
      }
    }

    _visibleText(el) {
      return String(el?.textContent || el?.getAttribute?.('aria-label') || '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    /**
     * Clique com sequÃªncia pointer/mouse + coordenadas
     * (cÃ©lulas do inventÃ¡rio costumam ignorar sÃ³ el.click()).
     */
    _humanClick(el, label) {
      if (!el) return false;
      const S = this._sel();
      try {
        S?.pulseHumanPresence?.();
      } catch (_) {}

      const target =
        el.querySelector?.('img') && el.classList?.contains?.('cell')
          ? el
          : el;
      try {
        target.scrollIntoView?.({ block: 'nearest', inline: 'nearest', behavior: 'instant' });
      } catch (_) {
        try {
          target.scrollIntoView?.(true);
        } catch (__) {}
      }

      let x = 0;
      let y = 0;
      try {
        const rect = target.getBoundingClientRect();
        if (rect && rect.width > 0 && rect.height > 0) {
          x = rect.left + rect.width / 2;
          y = rect.top + rect.height / 2;
        }
      } catch (_) {}

      const base = {
        bubbles: true,
        cancelable: true,
        view: window,
        clientX: x,
        clientY: y,
        screenX: x,
        screenY: y,
        button: 0,
        buttons: 1,
        detail: 1
      };

      try {
        // PointerEvent quando existir (jogos modernos escutam pointer*)
        if (typeof PointerEvent === 'function') {
          const pOpts = {
            ...base,
            pointerId: 1,
            pointerType: 'mouse',
            isPrimary: true,
            width: 1,
            height: 1,
            pressure: 0.5
          };
          target.dispatchEvent(new PointerEvent('pointerdown', pOpts));
          target.dispatchEvent(new PointerEvent('pointerup', { ...pOpts, buttons: 0, pressure: 0 }));
        }
      } catch (_) {}

      try {
        target.dispatchEvent(new MouseEvent('mousedown', base));
        target.dispatchEvent(new MouseEvent('mouseup', { ...base, buttons: 0 }));
        target.dispatchEvent(new MouseEvent('click', { ...base, buttons: 0 }));
      } catch (_) {}

      try {
        if (typeof target.click === 'function') target.click();
      } catch (_) {}

      this._log('click', { label, x, y, tag: target?.tagName });
      return true;
    }

    _clickSafe(el, label) {
      if (!el) return false;
      // NÃ£o bloquear por isClickable em cÃ©lulas de inventÃ¡rio â vÃ¡rias ficam
      // technicalmente ok mas o helper do seletor pode falhar com containers.
      try {
        const S = this._sel();
        if (S && typeof S.isClickable === 'function') {
          const isCell = !!el.closest?.('.cell, .invgrid');
          if (!isCell && !S.isClickable(el)) return false;
        }
      } catch (_) {}
      return this._humanClick(el, label);
    }

    /** Grids de inventÃ¡rio onde o anel vazio / tokens podem estar. */
    _itemGrids() {
      const S = this._sel();
      const out = [];
      const push = (el) => {
        if (el && !out.includes(el)) out.push(el);
      };
      if (S?.ITEMS?.BACKPACK_GRID) {
        push(S.findElement(S.ITEMS.BACKPACK_GRID, 'BACKPACK_GRID'));
      }
      if (S?.ITEMS?.INV_GRID) {
        push(S.findElement(S.ITEMS.INV_GRID, 'INV_GRID'));
      }
      push(document.querySelector('#backpack-grid'));
      push(document.querySelector('#inv-grid'));
      // slots de equipamento (anel etc.)
      document
        .querySelectorAll(
          '#eq-grid, #equip-grid, .eqgrid, .equip-grid, #player-equip, .eq-slots, #eq'
        )
        .forEach((el) => push(el));
      return out;
    }

    _isSilverTokenImg(img) {
      if (!img) return false;
      const alt = String(img.getAttribute('alt') || '').trim().toLowerCase();
      const src = String(img.getAttribute('src') || '');
      return (
        alt === SILVER_TOKEN_NAME ||
        src.includes('/object/' + SILVER_TOKEN_ID) ||
        src.includes('object/' + SILVER_TOKEN_ID + '.') ||
        /\/22516(\.png|\?)/.test(src)
      );
    }

    _countSilverTokens() {
      let total = 0;
      const roots = this._itemGrids();
      // fallback: documento inteiro (token fora do grid esperado)
      if (!roots.length) roots.push(document.body || document.documentElement);

      const seen = new Set();
      for (const root of roots) {
        if (!root?.querySelectorAll) continue;
        const cells = root.querySelectorAll('.cell, .mat');
        for (const cell of cells) {
          if (seen.has(cell)) continue;
          seen.add(cell);
          const img = cell.querySelector?.('img');
