// - Clica na aba â #daily-claim-btn â #daily-modal-close
// - Poll leve; apÃ³s coletar aplica cooldown longo (diÃ¡rio ~24h)

(function () {
  const POLL_MS = 12000;
  const STATUS_UI_MS = 1500;
  const MODAL_WAIT_MS = 6000;
  const SETTLE_MS = 800;
  const CLAIM_COOLDOWN_MS = 6 * 60 * 60 * 1000; // 6h (evita spam apÃ³s claim)
  const NO_BADGE_COOLDOWN_MS = 90 * 1000;
  const STORAGE_NEXT = '__baiakIdleColetarRecompensaNextAt';

  class BaiakIdleColetarRecompensaModule {
    constructor() {
      this._running = false;
      this._busy = false;
      this._pollTimer = null;
      this._statusTimer = null;
      this._observer = null;
      this._lastStatusKey = '';
      this._lastAction = '';
    }

    _log(msg, extra) {
      try {
        if (window.__BAIAKIDLE_DEBUG) {
          console.log('[BaiakIdle Coletar Rewards]', msg, extra || '');
        }
      } catch (_) {}
    }

    _sel() {
