      if (key === this._lastStatusKey) return;
      this._lastStatusKey = key;
      try {
        window.postMessage(
          {
            source: 'TIBIA_BOT_MAIN',
            type: 'MODULE_STATUS',
            payload: {
              botId: 'baiak_idle',
              botLabel: 'Baiak-Idle',
              moduleId: 'coletar_recompensa',
              moduleLabel: 'Daily Reward',
              status,
              remainingMs: 0,
              remainingText: String(remainingText || ''),
              running: !!this._running
            }
          },
          '*'
