    }

    _startStatusTicker() {
      if (this._statusTimer) return;
      const tick = () => {
        if (!this._running) {
          this._stopStatusTicker();
          this._emitStatus('stopped', '');
          return;
        }
        if (this._busy) {
          this._emitStatus('claiming', this._lastAction || 'â¦');
          return;
        }
        const next = this._getNextAt();
        if (next && next > Date.now()) {
          this._emitStatus('waiting', this._formatRemain(next - Date.now()));
          return;
        }
        if (this._isRewardAvailable()) {
          this._emitStatus('ready', 'disponÃ­vel');
        } else {
          this._emitStatus('idle', 'aguardando badge');
        }
      };
      tick();
      this._statusTimer = setInterval(tick, STATUS_UI_MS);
    }

    _stopStatusTicker() {
      if (this._statusTimer) {
        clearInterval(this._statusTimer);
        this._statusTimer = null;
      }
    }

    _formatRemain(ms) {
      const sec = Math.ceil(Math.max(0, ms) / 1000);
      if (sec < 60) return sec + 's';
      const m = Math.floor(sec / 60);
      const s = sec % 60;
      if (m < 60) return m + 'm' + (s ? String(s).padStart(2, '0') + 's' : '');
      const h = Math.floor(m / 60);
      const mm = m % 60;
      return h + 'h' + (mm ? String(mm).padStart(2, '0') + 'm' : '');
    }

    _getNextAt() {
      try {
        const raw = sessionStorage.getItem(STORAGE_NEXT);
        const n = raw ? parseInt(raw, 10) : 0;
        return Number.isFinite(n) ? n : 0;
