        return 0;
      }
    }

    _setNextAt(ts) {
      try {
        sessionStorage.setItem(STORAGE_NEXT, String(ts));
      } catch (_) {}
    }

    _visible(el) {
      if (!el) return false;
      try {
        const S = this._sel();
        if (S && typeof S.isClickable === 'function') {
          return !!S.isClickable(el);
