    }

    _claimBtn() {
      return (
        document.querySelector('#daily-claim-btn') ||
        document.querySelector('button.daily-claim-btn') ||
        document.querySelector('#daily-claim-slot button')
      );
    }

    _closeBtn() {
      return (
        document.querySelector('#daily-modal-close') ||
        document.querySelector('#daily-modal button.im-closebtn') ||
        document.querySelector('.daily-modal .im-closebtn')
      );
