    }

    _clickSafe(el, label) {
      if (!el) return false;
      try {
        const S = this._sel();
        if (S && typeof S.isClickable === 'function' && !S.isClickable(el)) {
          // tab/badge Ã s vezes falham isClickable; tenta o mesmo
          if (!el.id || (el.id !== 'tab-daily' && el.id !== 'daily-claim-btn' && el.id !== 'daily-modal-close')) {
            return false;
          }
        }
      } catch (_) {}
      return this._humanClick(el, label);
    }

    async _claimFlow() {
      this._lastAction = 'abrindo Dailyâ¦';
      const tab = this._dailyTab();
      if (!tab) {
        this._log('tab-daily ausente');
        return false;
      }

      // Se claim jÃ¡ visÃ­vel, pular abertura
      let claim = this._claimBtn();
      if (!(claim && this._visible(claim))) {
        this._clickSafe(tab, 'tab-daily');
        claim = await this._waitFor(() => {
