          return b && this._visible(b) && !b.disabled ? b : null;
        }, MODAL_WAIT_MS);
      }

      if (!claim) {
        this._log('claim btn nÃ£o apareceu');
        // fecha modal se abriu sem claim (jÃ¡ coletado)
        const closeOnly = this._closeBtn();
        if (closeOnly && this._visible(closeOnly)) {
          this._clickSafe(closeOnly, 'daily-modal-close empty');
        }
        return false;
      }

      this._lastAction = 'coletandoâ¦';
      this._clickSafe(claim, 'daily-claim-btn');
      await this._sleep(SETTLE_MS + 400);

      this._lastAction = 'fechandoâ¦';
      const close = await this._waitFor(() => {
        const b = this._closeBtn();
        return b && this._visible(b) ? b : null;
      }, 3000);
      if (close) {
        this._clickSafe(close, 'daily-modal-close');
        await this._sleep(SETTLE_MS);
