          this._log('claim ok');
        } else {
          this._setNextAt(Date.now() + NO_BADGE_COOLDOWN_MS);
        }
      } catch (err) {
        this._log('erro tick', err);
        this._setNextAt(Date.now() + NO_BADGE_COOLDOWN_MS);
      } finally {
        this._busy = false;
        this._lastAction = '';
      }
    }

    _scheduleCheck() {
      if (!this._running || this._busy) return;
      void this._tick();
    }

    start() {
      if (this._running) {
