        let full = String(raw || '')
          .replace(/\s+/g, ' ')
          .trim();
        if (!full || full === 'TibiaBot.Online') return;

        let className = String(classNameHint || '').trim();
        let display = full;
        if (typeof S?.parseClassAndName === 'function') {
          const p = S.parseClassAndName(full);
          if (p?.name) display = p.name;
