      const hit =
        alias.get(normKey(full)) ||
        alias.get(normKey(parsed)) ||
        alias.get(normKey(full.replace(/\s+/g, '')));
      if (hit) {
        return { key: normKey(hit), display: hit, party: true, label: full };
