        static _describeEl(el) {
            if (!el) return null;
            try {
                const tag = String(el.tagName || '').toLowerCase();
                const id = el.id ? '#' + el.id : '';
                const cls = el.className
                    ? '.' +
                      String(el.className)
                          .trim()
                          .split(/\s+/)
                          .slice(0, 4)
