                    if (input && typeof input.checked === 'boolean') checked = input.checked;
                }
                return {
                    tag: tag + id + cls,
                    text: text || '(sem texto)',
                    checked,
                    clickable: !!(window.BaiakIdleSeletores?.isClickable?.(el))
                };
            } catch (_) {
