                if (!bossBtn || !S.isClickable(bossBtn)) {
                    throw new Error('OpÃ§Ã£o Chefes nÃ£o encontrada no menu aberto');
                }
                bossBtn.click();
                this._log('Clicou em Chefes (data-tp=boss)');
                await this._sleep(STEP_MS);

                const started = Date.now();
